INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80991, 'spa', 'Acab (nombre propio)', 'Acab (nombre propio). Nombre propio Acab (''hermano del padre''), usado principalmente para Acab hijo de Omri, rey de Israel (r. ca. 874-853 a.C.), cuyo reinado politicamente poderoso pero espiritualmente ruinoso domina 1 Reyes 16:28-22:40 y resuena en 2 Reyes y 2 Cronicas. Su promocion del culto a Baal mediante Jezabel provoco la gran contienda en el monte Carmelo (1 R 18). Un segundo portador es Acab hijo de Colaias, falso profeta entre los exiliados babilonicos (Jer 29:21-22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81004, 'spa', 'uno (numeral cardinal)', 'El numeral cardinal ''uno'' en su sentido basico (940 apariciones), presente desde el primer capitulo del Genesis (''dia uno,'' Gn 1:5). Traducido universalmente como simple numeral — espanol uno/una, frances un, aleman eine — este sentido cubre usos adjetivales, sustantivados y en estado constructo. Abarca pasajes teologicamente cargados como Gn 2:24 (''una sola carne'') y Dt 6:4 (''el SENOR es uno'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81012, 'spa', 'como uno (comparativo)', 'Uso comparativo o enfatico que significa ''como uno, cual uno'' (11 apariciones). Las glosas multilingues reflejan la particula de simil: espanol ''como uno,'' aleman ''wie einer.'' En Gn 3:22 (''el hombre ha llegado a ser como uno de nosotros'') y 2 Cr 5:13 (trompetistas y cantores eran ''como uno''), la palabra trasciende el mero conteo para expresar unidad, semejanza o identidad colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81013, 'spa', 'una vez (temporal)', 'Uso temporal que significa ''una vez, en una ocasion'' (10 apariciones). Espanol una vez, aleman einmal y frances une fois confirman la funcion adverbial. Textos rituales clave incluyen Ex 30:10 (''una vez al ano Aaron hara expiacion'') y Lv 16:34 (''una vez al ano''), estableciendo la periodicidad liturgica. El paso de ''uno'' numerico a ''una vez'' temporal es natural en multiples lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81019, 'spa', 'primero (ordinal)', 'Uso ordinal que significa ''primero'' en lugar de ''uno'' (6 apariciones). Las lenguas meta emplean sistematicamente formas ordinales: espanol el primero/la primera, frances le premier, aleman der erste. Gn 2:11 nombra el ''primer'' rio; Ex 28:17 describe la ''primera'' hilera de piedras preciosas. El hebreo carece de un ordinal exclusivo para ''primero,'' confiando en אֶחָד antes de estandarizar רִאשׁוֹן.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81023, 'spa', 'unos pocos (indefinido)', 'Cuantificador indefinido que significa ''unos pocos, algunos'' (3 apariciones). Espanol algunos/unos pocos, aleman einige reemplazan el numeral en estos contextos. Gn 27:44 (''quedate con el unos pocos dias'') y Gn 29:20 (''le parecieron como pocos dias'') muestran indefinicion temporal, mientras Dn 11:20 lo emplea para un periodo breve indeterminado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81029, 'spa', 'cada uno (distributivo)', 'Uso distributivo que significa ''cada, cada uno'' (3 apariciones), con funcion pronominal. Frances chaque un, aleman jeder eins confirman la lectura distributiva. Nm 15:12 (''por cada uno''), Jue 8:18 (''cada uno parecia'') e Is 6:2 (''cada uno tenia seis alas'') muestran la palabra distribuyendo atributos entre individuos de un conjunto en vez de especificar una cantidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81032, 'spa', 'once (numeral compuesto)', 'El numeral compuesto ''once,'' formado con עָשָׂר ''diez'' (3 apariciones). Las lenguas meta usan lexemas propios: frances onze, espanol once, aleman elf, confirmando que se percibe como un numero unico y no como una frase. Gn 32:22 cuenta los once hijos de Jacob, Dt 1:2 mide ''once dias de camino'' y Jos 15:51 contabiliza once ciudades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81037, 'spa', 'Juncos de pantano', 'En Génesis, la palabra aparece dos veces en el sueño del faraón donde siete vacas gordas pacen entre los juncos junto al Nilo, escena típicamente egipcia de prosperidad agrícola. Job 8:11 pregunta retóricamente si los juncos pueden florecer sin pantano, convirtiéndolos en emblema de lo que no puede sobrevivir separado de su fuente vital. El préstamo del egipcio recuerda que Israel conocía estas plantas por su contacto directo con la tierra del Nilo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81043, 'spa', 'Gentilicio ahohita', 'Designacion gentilicia que significa ''el ahohita,'' identificando a una persona como descendiente del ancestro benjaminita Ahoah. Se emplea en los catalogos de los guerreros valientes de David (2 Sam 23:9, 28; 1 Cr 11:12, 29; 27:4). Cada aparicion esta vinculada a relatos de heroismo militar, senalando a este clan como uno de distincion en la cultura guerrera de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81045, 'spa', 'hacia atrás, detrás (dirección)', 'hacia atrás, detrás (dirección)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81047, 'spa', 'después, en adelante (temporal)', 'después, en adelante (temporal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81048, 'spa', 'cuartos traseros (de animales)', 'cuartos traseros (de animales)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81050, 'spa', 'occidente (dirección geográfica)', 'occidente (dirección geográfica)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81052, 'spa', 'espalda (parte del cuerpo / parte trasera)', 'espalda (parte del cuerpo / parte trasera)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81058, 'spa', 'hermana (consanguínea)', 'Hermana de sangre o parienta femenina cercana: el sentido dominante de parentesco en 113 ocurrencias. Sara es llamada hermana de Abraham (Gn 12:13; 20:2), Dina como hermana de los hijos de Jacob (Gn 34:13-31), Tamar y Absalón (2 S 13). En español hermana, en francés sœur y en alemán Schwester confirman uniformemente la relación familiar literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81063, 'spa', 'contraparte, una a otra', 'Extensión idiomática que significa ''contraparte, pieza correspondiente, una a otra'', aplicada a objetos inanimados emparejados. Las cortinas del tabernáculo se acoplan ''cada una a su hermana'' (Éx 26:3, 5-6) y las alas o tablas emparejadas quedan ''cada una frente a su hermana'' (Ez 1:9; 3:13). El español su hermana y el francés sa sœur conservan el posesivo femenino aun cuando el referente es un objeto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81101, 'spa', 'asir, agarrar fisicamente', 'asir, agarrar fisicamente. Sentido basico del Qal activo: asir, agarrar o tomar fisicamente a alguien o algo con la mano. El arabe akhadha (''tomar''), el coreano jabda (''agarrar'') y el suajili -shika (''asir'') son paralelos de este significado primario. Jacob agarrando el talon de Esau (Gen 25:26) y Moises asiendo la serpiente (Ex 4:4) son casos paradigmaticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81102, 'spa', 'ser tomado, ser seleccionado', 'ser tomado, ser seleccionado. Sentido del participio pasivo Qal: ser tomado o seleccionado para un proposito, frecuentemente en el contexto de suertes, porciones o seleccion censal. Las cinco ocurrencias se concentran en Numeros 31 (reparto del botin de guerra) y 1 Cronicas 24 (seleccion de turnos sacerdotales).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81106, 'spa', 'sujeto, unido, trabado', 'sujeto, unido, trabado. Hofal causativo-pasivo y formas afines que significan estar sujeto, unido, trabado o empalmado, aplicado a elementos arquitectonicos como vigas, cortinas y puertas. Las camaras laterales del templo de Salomon sujetas a la casa (1 R 6:10) y las colgaduras del palacio fijadas con cordones en Ester 1:6 ejemplifican este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81107, 'spa', 'tomar posesion de tierra', 'tomar posesion de tierra. Sentido del Nifal que significa tomar posesion o adquirir tierra y propiedades, un significado juridico-territorial distinto de la simple aprehension fisica. Abarca las narraciones patriarcales (Gen 34:10; 47:27) hasta el asentamiento de la conquista (Num 32:30; Jos 22:9, 19). El hebreo extiende singularmente la raiz de ''agarrar'' hacia la posesion legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81116, 'spa', 'prender figuradamente (emocion abrumadora)', 'prender figuradamente (emocion abrumadora). Extension figurada donde una emocion, temor o temblor es el sujeto gramatical que ''agarra'' a una persona, dejandola abrumada o paralizada. El arabe istawla (''dominar'') y el coreano salojapta (''prender'') confirman el patron translinguistico de metaforas de aprehension para la experiencia emocional. El Cantico del Mar (Ex 15:14-15) es emblematico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81118, 'spa', 'ser atrapado, ser enredado', 'ser atrapado, ser enredado. Sentido Nifal y Qal pasivo de quedar atrapado o enredado, como en una espesura o trampa. El carnero de Abraham trabado por los cuernos en un matorral (Gen 22:13) y la observacion de Qohelet de que las personas caen en trampas como peces y aves (Ecl 9:12) son los ejemplos clave.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81152, 'spa', 'cubrir (uso cosmico unico)', 'cubrir (uso cosmico unico). Ocurrencia singular en Job 26:9 donde Dios ''cubre'' o ''agarra'' la faz de la luna llena, extendiendo nubes sobre ella. Las glosas multilingues divergen: espanol ''cubriendo'', frances y aleman conservan ''asir''. Esta aplicacion cosmica extiende la metafora de aprehension al poder soberano de Dios sobre los fenomenos celestes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81162, 'spa', 'Acaz, rey de Judá', 'Acaz, rey de Judá');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81166, 'spa', 'propiedad territorial, posesion', 'propiedad territorial, posesion. Propiedad territorial mantenida como posesion permanente y tipicamente hereditaria, especialmente en la legislacion sacerdotal que rige la restauracion del Jubileo (Lv 25:10, 13, 25-28), la herencia tribal (Nm 27:4; 32:5) y las asignaciones leviticas (Nm 35:8; Ez 44-48). La compra de Macpela por Abraham como posesion funeraria (Gen 23:4, 9, 20) ancla el termino en la narrativa patriarcal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81198, 'spa', 'Ocozías (nombre propio)', 'Ocozías (nombre propio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81210, 'spa', 'Nombre propio masculino que significa ''hermano de Yah(vé),'' aplicado a al menos ', 'Nombre propio masculino que significa ''hermano de Yah(vé),'' aplicado a al menos seis individuos distintos en la Biblia hebrea. El más significativo teológicamente es Ahías el silonita, profeta que predijo la secesión del norte rasgando su vestido en doce pedazos (1 Re 11:29-30) y que luego pronunció juicio sobre la casa de Jeroboam (1 Re 14:1-18). Otros portadores incluyen un sacerdote bajo Saúl (1 Sam 14:3), un escriba real (1 Re 4:3) y el padre del rey Baasa (1 Re 15:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81220, 'spa', 'Ahío (nombre propio)', 'Ahío (אַחְיוֹ, ''fraternal'' o ''hermano''), nombre propio de varios israelitas. El más notable caminaba delante del arca junto a su hermano Uza cuando David la transportó en un carro nuevo (2 Sam 6:3-4; 1 Chr 13:7). Otros dos portadores del nombre aparecen en genealogías benjaminitas (1 Chr 8:14, 31; 9:37). La Septuaginta a veces lee la palabra como ''sus hermanos'' (אֶחָיו), reflejando la ambigüedad ortográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81222, 'spa', 'Ahitob (nombre propio) — Nombre propio hebreo (אֲחִיטוּב, ''mi hermano es bondad''', 'Ahitob (nombre propio) — Nombre propio hebreo (אֲחִיטוּב, ''mi hermano es bondad'') llevado por al menos dos figuras sacerdotales: (1) nieto de Elí y padre de Ahimélec, vinculando el sacerdocio elida con la tragedia de Nob (1 S 14:3; 22:9-20); y (2) padre de Sadoc, pilar de la dinastía sadoquita (2 S 8:17; 1 Cr 6:7-8). Las genealogías postexílicas continúan el nombre (Esd 7:2; Neh 11:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81225, 'spa', 'Nombre propio Ajilud', 'El nombre propio Ajilud, que identifica a dos hombres en la administracion davidico-salomonica: (a) padre de Josafat, cronista real bajo David y Salomon (2 Sam 8:16; 20:24; 1 R 4:3; 1 Cr 18:15), y (b) padre de Baana, gobernador de Salomon en el distrito de Jezreel y Bet-sean (1 R 4:12). La etimologia ''hermano de un nino'' es incierta, pero podria reflejar costumbres de denominacion segun orden de nacimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81227, 'spa', 'Ahimelec (nombre propio)', 'Ahimelec (nombre propio). Nombre propio hebreo que significa ''mi hermano es rey'', referido principalmente al sacerdote en Nob que proveyó a David del pan de la proposición y la espada de Goliat (1 Sam 21:1-9), acto que condujo a la matanza de los sacerdotes de Nob ordenada por Saúl (1 Sam 22:9-20). Jesús cita este episodio en Marcos 2:26. El nombre también pertenece a un compañero hitita de David (1 Sam 26:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81234, 'spa', 'Nombre personal', 'Ajimán — nombre personal que probablemente significa «mi hermano es un don». El Ajimán anaceo (Nm 13:22; Jos 15:14; Jue 1:10) fue uno de los tres gigantes cuya presencia aterrorizó a los espías, pero que finalmente fue desposeído cuando Caleb y Judá tomaron Hebrón. El Ajimán levita (1 Cr 9:17) servía como portero del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81235, 'spa', 'Ahimaas (nombre propio) — Nombre propio hebreo (אֲחִימַעַץ, ''mi hermano es ira/c', 'Ahimaas (nombre propio) — Nombre propio hebreo (אֲחִימַעַץ, ''mi hermano es ira/consejo'') aplicado a al menos dos individuos: (1) hijo de Sadoc, mensajero de inteligencia de David durante la revuelta de Absalón (2 S 15:27, 36; 17:17-20), quien corrió para informar sobre la muerte de Absalón (2 S 18:19-29), atestiguado en las genealogías del Cronista (1 Cr 6:8-9); y (2) suegro de Saúl (1 S 14:50). Posiblemente también un gobernador de distrito de Salomón (1 R 4:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81241, 'spa', 'Ajinoam (nombre propio)', 'El nombre propio Ajinoam, referido a dos mujeres bíblicas: (1) Ajinoam hija de Ajimaas, esposa del rey Saúl (1 S 14:50), mencionada una sola vez; y (2) Ajinoam la jezreelita, esposa de David que compartió sus años de huida en territorio filisteo y fue capturada en Siclag antes de ser rescatada (1 S 25:43; 27:3; 30:5; 2 S 2:2; 3:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81244, 'spa', 'Nombre personal', 'Ahisamac aparece únicamente como padre de Aholiab en Éxodo 31:6, 35:34 y 38:23, donde su hijo es identificado repetidamente como artesano divinamente dotado. La identificación patronímica (''hijo de Ahisamac, de la tribu de Dan'') subraya la importancia del linaje en la memoria comunitaria de Israel. Aunque no se describe al propio Ahisamac, su nombre perduró a través de la extraordinaria contribución de su hijo al tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81245, 'spa', 'Ahiezer (nombre propio)', 'Ahiezer (אֲחִיעֶזֶר, ''mi hermano es ayuda''), nombre propio masculino. El portador principal es el hijo de Amisadai, jefe de Dan durante el desierto, presente en censos y ofrendas del tabernáculo (Num 1:12; 2:25; 7:66, 71; 10:25). Un segundo Ahiezer figura entre los guerreros benjaminitas que se unieron a David en Siclag (1 Cr 12:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81246, 'spa', 'Ahicam (nombre propio)', 'Ahicam (nombre propio). El nombre propio Ahicam (אֲחִיקָם, ''mi hermano se ha levantado''), referido al hijo de Safán que sirvió en la corte de Josías y posteriormente protegió a Jeremías. Aparece en el relato de la reforma de Josías (2 R 22:12, 14; 2 Cr 34:20), en la narrativa del rescate de Jeremías de quienes buscaban su muerte (Jer 26:24) y extensamente como padre del gobernador Gedalías (Jer 39:14; 40:5-43:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81251, 'spa', 'Nombre propio Ahira', 'El nombre propio Ahira (''mi hermano es malo'' o posiblemente ''mi hermano es amigo''), que designa al hijo de Enan, jefe tribal de Neftali durante el periodo del desierto. Sus cinco apariciones se hallan en Numeros, vinculadas a la organizacion del campamento y el culto de Israel: el registro censal (Nm 1:15), las posiciones tribales (Nm 2:29), las ofrendas de dedicacion del duodecimo dia (Nm 7:78, 83) y el orden de marcha (Nm 10:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81254, 'spa', 'Ahitofel (nombre propio, consejero de David)', 'Ahitofel (nombre propio, consejero de David). El nombre personal Ahitofel (אֲחִיתֹפֶל), que identifica al consejero de David procedente de Guiló que desertó hacia Absalón. Las 20 apariciones se concentran en la narrativa de Absalón (2 Sam 15-17) y dos noticias resumidas (2 Sam 23:34; 1 Cr 27:33-34). Las variaciones ortográficas en las traducciones reflejan opciones de transliteración más que diferencias semánticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81264, 'spa', 'Demorar, tardar, detenerse o ser lento en venir o actuar (Piel intransitivo)', 'Demorar, tardar, detenerse o ser lento en venir o actuar (Piel intransitivo). Abarca diecisiete ocurrencias que van desde la tardanza de Jacob con Laban (Gen 32:4) hasta la promesa profetica de que la salvacion de Dios no tardara (Isa 46:13; Hab 2:3; Dan 9:19). La forma participial en Proverbios 23:30 describe a quienes ''se demoran mucho'' con el vino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81279, 'spa', 'Detener o retener a otra persona (Piel transitivo)', 'Detener o retener a otra persona (Piel transitivo). La unica ocurrencia en Genesis 24:56, donde el siervo de Abraham insta a la familia de Laban ''no me detengais'', cambia el marco semantico: el sujeto causa la demora de otro en lugar de experimentarla el mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81280, 'spa', 'después de (temporal)', 'Sucesión temporal: después, posteriormente, a continuación de un evento en el tiempo. La legislación sacerdotal en Levítico y Números emplea repetidamente וְאַחַר para marcar secuencias rituales (Lv 14:8; 15:28). Las traducciones después de (esp.) y nach (al.) confirman esta lectura temporal como distinta de la persecución espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81281, 'spa', 'detrás de, tras (espacial)', 'Posición espacial posterior o de seguimiento en persecución, incluido el sentido direccional ''desde atrás'' con la preposición מִן. Las traducciones emplean consistentemente términos espaciales: detrás de (esp.), hinter (al.), après en contextos espaciales (fr.). Frecuente con הָלַךְ (''ir/caminar tras'') para describir el seguimiento de un líder, ejército o deidad (Gn 37:17; 1 R 18:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81329, 'spa', 'Secuencia temporal profética', 'La expresión aparece en la interpretación que Daniel hace de visiones reales acerca de reinos futuros. En Daniel 2:29 y 2:45 introduce revelaciones sobre ''lo que será después'', la sucesión de imperios que Dios ha predeterminado. Daniel 7:24 la usa para describir un rey que surgirá ''después de ellos'', siguiendo a los gobernantes previos en la secuencia de la historia profética. La forma aramea refleja el contexto lingüístico de la corte babilónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81330, 'spa', 'otro, otra, diferente', 'Otro, otra o diferente: el sentido adjetival primario que designa a una persona, cosa o grupo adicional o distinto. Es el uso predominante en todas las formas gramaticales (masculino, femenino, singular, plural). Gn 29:27 ilustra ''otros siete años''; Dt 5:7 advierte contra ''otros dioses'' (אֱלֹהִים אֲחֵרִים). El dominio semántico es el de la alteridad simple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81338, 'spa', 'siguiente, próximo', 'Siguiente o próximo en orden temporal o secuencial: un uso más restringido donde אַחֵר indica no solo diferencia sino sucesión. En Gn 17:21 Dios promete a Isaac ''por este tiempo el año siguiente''; Jl 1:3 ordena transmitir el relato a ''la generación venidera''. Sal 109:8 y 109:13 lo emplean para la sucesión en un cargo. Este matiz temporal lo distingue del sentido genérico de alteridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81351, 'spa', 'ultimo, final en secuencia', 'ultimo, final en secuencia. Ultimo o final en una secuencia ordenada, ya sea ordinal o temporal. Genesis 33:2 situa a Raquel al final de la procesion, 2 Samuel 23:1 recoge las ''ultimas palabras'' de David, e Isaias 44:6 declara al SENOR ''el ultimo'' -- el termino absoluto de toda secuencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81353, 'spa', 'occidental', 'occidental. Sentido direccional que surge de la orientacion semitica mirando al este, donde ''detras'' equivale a ''oeste''. Deuteronomio 11:24 nombra ''el mar occidental'' (Mediterraneo), Deuteronomio 34:2 contempla la tierra hasta el mar occidental, y Zacarias 14:8 profetiza aguas vivas fluyendo hacia ''el mar occidental''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81354, 'spa', 'postrero, condicion posterior', 'postrero, condicion posterior. El estado o condicion posterior contrastada con una anterior, como en ''la postreria'' o ''la lluvia tardia''. Rut 3:10 elogia la ''bondad postrera'' de Rut que supera a la primera, Deuteronomio 24:3 habla de un ''ultimo marido'', e Isaias 9:1 contrasta un tiempo anterior de tinieblas con una gloria posterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81355, 'spa', 'futuro, venidero', 'futuro, venidero. Futuro, posterior o venidero, proyectando el sentido de ''despues'' hacia adelante en el tiempo. Deuteronomio 29:22 habla de una ''generacion futura'' que presenciara el juicio, Salmo 78:4-6 transmite el testimonio a ''una generacion venidera'', y Salmo 102:18 escribe para ''un pueblo aun por crear''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81358, 'spa', 'al fin, finalmente (adverbial)', 'al fin, finalmente (adverbial). Uso adverbial con preposiciones (beth, lamed) para expresar ''al fin'', ''finalmente'' o ''despues''. Numeros 2:31 indica que el campamento de Dan marcha ''al ultimo'', Deuteronomio 13:9 prescribe que la mano del testigo caiga ''al final'', y 2 Samuel 2:26 pregunta si la espada devorara ''hasta el fin''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81365, 'spa', 'los venideros, descendientes', 'los venideros, descendientes. Uso sustantivado para personas posteriores, descendientes o generaciones subsiguientes. Job 18:20 describe a ''los que vienen despues'' horrorizandose, Eclesiastes 1:11 advierte que no habra memoria entre ''los que vengan despues'', y Eclesiastes 4:16 lamenta que ''los ultimos'' no hallan satisfaccion en un rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81368, 'spa', 'el Postrero (titulo divino)', 'el Postrero (titulo divino). Ocurrencia teologicamente cargada en Job 19:25 donde Job declara que su Redentor es ''el Postrero'' -- aquel que permanece y se levanta al final. Esta unica atestacion porta resonancias del epiteto divino de Isaias 44:6 y 48:12, que nombra a Dios como la realidad ultima y perdurable mas alla de toda secuencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81381, 'spa', 'Otro/otra (adjetivo arameo)', 'Otro u otra (arameo אָחֳרִי), usado atributiva y predicativamente en Daniel para distinguir entidades sucesivas en visiones proféticas. En la estatua de Nabucodonosor introduce los reinos inferiores tras Babilonia (Dan 2:39). En la visión de las cuatro bestias marca cada criatura que surge del mar (Dan 7:5-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81384, 'spa', 'periodo final, fin de los dias', 'periodo final, fin de los dias. El periodo final o ultima fase de un lapso temporal, especialmente en contextos escatologicos y profeticos: ''en los postreros dias'' (Gen 49:1; Dt 4:30; Dan 10:14). Este sentido temporal se matiza con la expectativa apocaliptica -- el periodo decisivo en que los propositos de Dios seran revelados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81385, 'spa', 'desenlace, destino, fin', 'desenlace, destino, fin. El desenlace, destino o resultado final de una persona, nacion o curso de accion. Es el sentido mas frecuente, con fuertes matices morales y judiciales: ''considerad su postrimeria'' (Dt 32:29), ''el fin de los impios'' (Sal 73:17), o las palabras del necio cuyo ''fin es locura'' (Ecl 10:13). El espanol emplea tanto ''fin'' como ''postreria''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81386, 'spa', 'futuro, esperanza', 'futuro, esperanza. Un futuro o expectativa esperanzadora, especialmente el buen desenlace que Dios promete con certeza. Jeremias 29:11 -- ''planes de un futuro y una esperanza'' -- es el versiculo paradigmatico, donde la palabra es paralela a ''esperanza'' misma. Proverbios la empareja de modo similar: ''ciertamente hay un porvenir, y tu esperanza no sera cortada'' (Prov 23:18; 24:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81393, 'spa', 'remanente, sobrevivientes', 'remanente, sobrevivientes. El remanente o los sobrevivientes que quedan tras la catastrofe o el juicio. En Ezequiel 23:25 el ''resto'' de un pueblo enfrenta mas castigo, y Amos 9:1 habla de los ultimos sobrevivientes. Este sentido concreto y colectivo es una extension natural del final temporal al residuo que permanece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81394, 'spa', 'extremo espacial, confin', 'extremo espacial, confin. La extremidad espacial o el confin mas lejano de un lugar. Salmo 139:9 -- ''si tomara las alas del alba y habitara en el extremo del mar'' -- es la unica instancia clara. El espanol ''confines'' preserva este raro uso espacial, donde la metafora temporal raiz (''lo que viene despues'') se extiende a la distancia fisica: el lugar que queda mas alla de todo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81403, 'spa', 'posteridad, descendientes', 'posteridad, descendientes. Posteridad o descendientes -- las personas que vienen despues de alguien, su linaje futuro. Salmo 109:13 pide que la posteridad del enemigo sea cortada; Daniel 11:4 dice que un reino no pasara a ''su posteridad''. El enfasis recae en la continuacion genealogica mas que en la supervivencia tras un desastre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81416, 'spa', 'Otro, distinto', 'Otro, diferente — marcando algo categoricamente distinto de lo que precede. En Dn 2:11 ningun ''otro'' puede revelar el sueno del rey; en Dn 2:44 un reino que jamas pasara a ''otro'' pueblo; en Dn 3:29 ningun ''otro'' dios puede librar asi; en Dn 5:17 da tus recompensas a ''otro''; en Dn 7:24 se levantara ''otro'' rey despues de los diez. El espanol ''otro'' y el frances ''autre'' reflejan consistentemente este sentido de alteridad radical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81417, 'spa', 'Hacia atrás', 'Hacia atrás, en dirección inversa o de retroceso, describiendo movimiento físico opuesto a la orientación normal o hacia adelante. Se usa para Sem y Jafet cubriendo a su padre mientras caminaban de espaldas (Gn 9:23), la caída mortal de Elí hacia atrás desde su silla (1 S 4:18), la oración de Elías pidiendo que Dios volviera los corazones del pueblo (1 R 18:37), y dramáticamente el retroceso de la sombra del sol diez gradas como señal para Ezequías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81419, 'spa', 'Sátrapas persas', 'Sátrapas: gobernadores imperiales persas sobre las provincias. En los cuatro pasajes donde aparece el término (Esd 8:36; Est 3:12; 8:9; 9:3), los sátrapas son presentados como poderosos administradores que reciben y ejecutan decretos reales. Las traducciones al español conservan el título como ''sátrapas'', reconociéndolo como cargo político establecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81420, 'spa', 'Los sátrapas', 'Gobernador provincial persa de alto rango (sátrapa), que aparece en las porciones arameas de Daniel donde describe la jerarquía administrativa imperial. En Dn 3:2-3 los sátrapas son convocados junto con prefectos y gobernadores a la llanura de Dura; en Dn 3:27 presencian la supervivencia milagrosa de los tres hombres en el horno; en Dn 6:1-2 son organizados bajo supervisores, entre ellos el propio Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81422, 'spa', 'Asuero (nombre propio)', 'Asuero (nombre propio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81429, 'spa', 'Suavemente, despacio', 'Suavemente, despacio — describiendo accion quieta, cuidadosa o tierna. Usado adverbialmente para Jacob conduciendo sus rebanos a paso lento (Gn 33:14), David suplicando dulzura hacia Absalon (2 Sam 18:5), Acab caminando abatido en penitencia (1 R 21:27), una palabra dicha con suavidad (Job 15:11) y las aguas de Siloe fluyendo mansas (Is 8:6). El par espanol ''despacio/suave'' refleja la doble dimension fisica y emocional del termino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81430, 'spa', 'Espino, zarza (planta)', 'Arbusto espinoso o zarza, identificado con el género Rhamnus. En la fábula de Jotam (Jue 9:14-15), personifica al gobernante indigno: cuando los árboles nobles rehusaron, la zarza aceptó la realeza y amenazó con fuego. En Sal 58:9 sirve como imagen de destrucción repentina. Cognados en arameo (אַטְדָּא) y acadio confirman la antigüedad del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81431, 'spa', 'Atad (topónimo)', 'Nombre propio de lugar, Atad, que aparece solo en la expresión ''era de Atad'' (גֹּרֶן הָאָטָד, Gn 50:10-11). Este sitio al otro lado del Jordán fue el lugar de un duelo de siete días por Jacob durante su procesión fúnebre de Egipto a Canaán. Aunque etimológicamente vinculado al espino, funciona como topónimo fijo en todas las traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81434, 'spa', 'Cerrar, tapar (oídos)', 'Cerrar u obstruir los oídos o los labios, describiendo un rechazo deliberado a escuchar o a hablar. Se emplea en el Qal y Hifil: taparse los oídos ante el clamor del pobre (Prov 21:13), guardar silencio prudente cerrando los labios (Prov 17:28) y negarse a oír la corrupción moral (Isa 33:15). En el Salmo 58:4-5, los impíos se comparan con una víbora sorda que se tapa el oído ante el encantador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81435, 'spa', 'Estrechas, cerradas (ventanas)', 'Cerradas, estrechas o enrejadas, describiendo las aberturas de las ventanas en construcciones del templo. El participio pasivo Qal אֲטֻמִים/אֲטֻמוֹת caracteriza las ventanas (חַלּוֹנוֹת) como estrechas o empotradas. En 1 Reyes 6:4, el Templo de Salomón tiene ''ventanas estrechas y cerradas''. El templo visionario de Ezequiel presenta el mismo tipo de ventanas (Ez 40:16; 41:16, 26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81439, 'spa', 'Nombre propio postexílico', 'El nombre propio Ater, que designa familias e individuos judíos postexílicos en los relatos de la restauración. Identifica: (a) un jefe de clan cuyos descendientes regresaron con Zorobabel (Esd 2:16; Neh 7:21), (b) una familia de porteros (Esd 2:42; Neh 7:45) y (c) un firmante del pacto en Nehemías 10:17. El significado ''atador'' o ''cerrado'' es incierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81441, 'spa', '¿dónde? (interrogativo de lugar)', '¿dónde? (interrogativo de lugar)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81449, 'spa', '¿cuál? ¿qué? (interrogativo de selección)', '¿cuál? ¿qué? (interrogativo de selección)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81460, 'spa', '¿cómo? (interrogativo de manera)', '¿cómo? (interrogativo de manera)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81465, 'spa', 'Chacales de ruinas', 'Isaías 13:22 y 34:14 retratan Babilonia y Edom invadidas por estas criaturas, cuyos aullidos resuenan en los palacios en lugar de voces humanas. Jeremías 50:39 profetiza igualmente que Babilonia se convertirá en morada de chacales junto con otras bestias del desierto. La asociación constante con ciudades arruinadas convierte al chacal en símbolo auditivo y visual de devastación irreversible, lugares donde el juicio de Dios ha transformado la civilización en páramo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81466, 'spa', 'isla, costa', 'isla, costa');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81480, 'spa', 'enemigo, adversario', 'Participio activo qal sustantivado que designa a cualquier persona, grupo o potencia que actúa con hostilidad. Se emplea para enemigos personales (1 S 24:5), ejércitos extranjeros desplegados contra Israel (Lv 26:7-8) y hasta para Dios mismo cuando trata a su pueblo como adversario (Lm 2:5). Las traducciones en los 43 idiomas lo vierten uniformemente con un solo vocablo de enemistad, confirmando la ausencia de distinciones semánticas internas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81549, 'spa', 'Enemistad profunda', 'Enemistad, hostilidad profunda entre personas o pueblos. En Gn 3:15 designa el antagonismo primordial que Dios pone entre la serpiente y la mujer — el protoevangelio. En las leyes sobre homicidio de Nm 35:21-22 distingue el asesinato premeditado (motivado por enemistad) del homicidio involuntario. Ezequiel aplica la expresión אֵיבַת עוֹלָם (''enemistad perpetua'') a los filisteos (25:15) y a Edom (35:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81550, 'spa', 'Calamidad repentina y devastadora o ruina, empleada en contextos poéticos y prof', 'Calamidad repentina y devastadora o ruina, empleada en contextos poéticos y proféticos para referirse a una desgracia catastrófica. Aplicada nacionalmente a la apostasía de Israel (Jer 18:17), a naciones extranjeras bajo juicio divino como Moab (Jer 48:16) y Edom (Jer 49:8; Abd 13), y personalmente al justo que sufre (2 Sam 22:19; Sal 18:19) y al malvado que cosecha consecuencias (Job 18:12; 21:17; Pr 1:26-27). El cognado árabe sugiere algo que ''agobia'' o ''doblega'' a la persona bajo su peso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81565, 'spa', 'Ave rapaz inmunda', 'Levítico 11:14 y Deuteronomio 14:13 clasifican al halcón entre las aves inmundas, usando la frase «según su especie» para indicar toda una familia de rapaces. Job 28:7 invoca la legendaria agudeza visual del halcón al describir un sendero oculto «que ningún ave de rapiña conoce y que el ojo del halcón no ha visto», enfatizando misterios que escapan incluso a la vista más penetrante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81566, 'spa', 'Aiah (nombre propio)', 'Aiah (אַיָּה, probablemente ''halcón''), nombre propio de dos varones. Uno es un horita de Seír entre los clanes de Edom (Gn 36:24; 1 Cr 1:40). El otro es padre de Rizpa, concubina de Saúl: tras la entrega de sus hijos a los gabaonitas, ella guarda sus cuerpos hasta que David les concede sepultura (2 Sam 21:8-11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81570, 'spa', '¿dónde? (interrogativo de ubicación)', '¿dónde? (interrogativo de ubicación)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81576, 'spa', 'Job (nombre propio)', 'Job (nombre propio). Nombre propio del patriarca justo de Uz. Las 58 ocurrencias se refieren al mismo individuo: 56 dentro del libro de Job y dos en Ezequiel 14:14, 20, donde ejemplifica la piedad personal. El espanol y el frances conservan ''Job'', mientras que el aleman emplea ''Hiob'' y las transliteraciones hebreas dan ''Iyov''. La etimologia del nombre sigue siendo debatida -- posiblemente ''objeto de enemistad'' de la raiz איב.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81581, 'spa', 'Nombre propio femenino Jezabel (אִיזֶבֶל), referido a la hija de Etbaal rey de T', 'Nombre propio femenino Jezabel (אִיזֶבֶל), referido a la hija de Etbaal rey de Tiro que se casó con Acab y llegó a ser reina del reino del norte de Israel. Las 22 ocurrencias aparecen en 1 Reyes 16-21 y 2 Reyes 9, abarcando su presentación, su campaña contra los profetas de YHWH, el incidente de Nabot y su dramática muerte. Promovió activamente la adoración a Baal, sostuvo a cientos de profetas paganos y persiguió sistemáticamente a los profetas del SEÑOR (1 Re 18:4, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81585, 'spa', '!como! (adverbio exclamativo/interrogativo)', '!como! (adverbio exclamativo/interrogativo). Adverbio exclamativo e interrogativo que expresa modo, asombro, consternacion o protesta retorica. En contextos de lamento abre gritos de desolacion: ''!Como han caido los valientes!'' (2 Sam 1:19); ''!Como caiste del cielo!'' (Isa 14:12). En uso interrogativo enmarca expostulaciones de imposibilidad o protesta: ''!Como puedo yo solo soportar vuestra carga?'' (Dt 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81588, 'spa', 'Adverbio interrogativo o exclamativo que significa ''¿como?'' o ''¡como!'', pregunta', 'Adverbio interrogativo o exclamativo que significa ''¿como?'' o ''¡como!'', preguntando sobre la manera (Deut 1:12; 7:17; 12:30; 18:21) o expresando asombro y lamento (Isa 1:21; Lam 1:1; 2:1; 4:1-2). El libro de Lamentaciones toma su nombre hebreo de este grito inicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81589, 'spa', 'Adverbio locativo que significa ''¿donde?'', atestiguado unicamente en Cantar de l', 'Adverbio locativo que significa ''¿donde?'', atestiguado unicamente en Cantar de los Cantares 1:7 (dos veces), probablemente reflejando un uso dialectal del norte de Israel o influencia aramea. Las formas cognadas en arameo eikha y siriaco aikho significan ambas ''¿donde?'', lo que apoya este sentido geografico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81590, 'spa', 'Interrogación enfática', '¡¿Cómo?! — interrogación enfática que expresa intensidad emocional, consternación o perplejidad. La doble aparición en Ester 8:6 transmite la súplica angustiada de Ester ante el rey, mientras que el par en Cantares 5:3 expresa la tierna reluctancia de la amada. La partícula compuesta intensifica la fuerza del interrogativo simple, dotándolo de carga retórica y afectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81594, 'spa', 'carnero (oveja macho)', 'Oveja macho adulta, prominente en contextos sacrificiales, agropecuarios, económicos y visionarios de la Biblia hebrea. Aparece como sacrificio sustitutivo de Abraham (Gn 22:13), como animal prescrito para la consagración sacerdotal y las ofrendas por la culpa (Éx 29:15; Lv 5:15), como mercancía de comercio y tributo (2 R 3:4; 2 Cr 17:11) y como símbolo apocalíptico de poder real (Dn 8:3). Todas las lenguas convergen en su término estándar para oveja macho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81618, 'spa', 'pilar o jamba de entrada', 'pilar o jamba de entrada');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81625, 'spa', 'poste o dintel de puerta', 'poste o dintel de puerta');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81628, 'spa', 'Caudillos o poderosos', 'Éxodo 15:15 relata cómo el temblor se apoderó de «los caudillos de Moab» al presenciar la liberación de Israel en el mar. Ezequiel 17:13 y 31:11 se refieren a líderes prominentes: «el poderoso de las naciones» o «los jefes de la tierra». El vínculo metafórico con el carnero —que guía y protege al rebaño— sugiere fuerza, prominencia y autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81629, 'spa', 'Encinas o terebintos', 'Isaías 1:29 advierte que Israel se avergonzará de «las encinas que codiciaron», árboles bajo los cuales se practicaba culto ilícito. Isaías 61:3 transforma la imagen positivamente, llamando a los redimidos «robles de justicia», firmes y perdurables. Ezequiel 31:14 podría usar el término para los soberbios y altivos. A lo largo de estos pasajes, las traducciones reflejan la incertidumbre entre encina y terebinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81631, 'spa', 'Ciervo, venado — Macho de ciervo o venado como animal limpio permitido para cons', 'Ciervo, venado — Macho de ciervo o venado como animal limpio permitido para consumo según la ley mosaica. Enumerado junto con la gacela en las disposiciones dietéticas de Deuteronomio (Dt 12:15, 22; 14:5) y servido en la corte de Salomón (1 R 4:23). Caza que podían comer tanto personas ritualmente puras como impuras. En la poesía, es símbolo de anhelo espiritual (Sal 42:1), belleza del amado (Cnt 2:9) y restauración futura de los débiles (Is 35:6). El árabe أَيَّل identifica la misma especie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81639, 'spa', 'Cierva, gacela hembra', 'Sustantivo femenino אַיָּלָה que designa a la hembra del ciervo (cierva), empleado en contextos poéticos, sapienciales y proféticos como símbolo de gracia y agilidad. En Génesis 49:21, Neftalí es comparado con una cierva suelta; en 2 Samuel 22:34, Salmo 18:33 y Habacuc 3:19, Dios hace los pies del salmista como los de una cierva —veloces y seguros en las alturas. Job 39:1 y Salmo 29:9 describen a la cierva pariendo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81645, 'spa', 'Elón (nombre propio)', 'Nombre propio Elón (que significa ''encina'' o ''terebinto''), aplicado a múltiples individuos y una localidad: (a) Elón el hitita, padre de Basemat/Ada, esposa de Esaú (Gn 26:34; 36:2); (b) Elón hijo de Zabulón, ancestro epónimo del clan elonita (Gn 46:14; Nm 26:26); (c) Elón el zebulonita, juez menor que juzgó a Israel diez años antes de ser sepultado en Ajalón (Jue 12:11-12); y (d) una ciudad en el territorio de Dan (Jos 19:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81649, 'spa', 'Ajalón (topónimo) — Ciudad en las colinas de la Sefela dentro del territorio tri', 'Ajalón (topónimo) — Ciudad en las colinas de la Sefela dentro del territorio tribal de Dan, identificada con la moderna Yalo al noroeste de Jerusalén. Célebre por la oración de Josué en el campo de batalla pidiendo que la luna se detuviera sobre su valle (Jos 10:12). Incluida entre las ciudades de Dan (Jos 19:42), asignada a los levitas coatitas (Jos 21:24; 1 Cr 6:69) y mencionada en la resistencia amorrea (Jue 1:35). Posteriormente fortificada por Roboam (2 Cr 11:10) y capturada por los filisteos en tiempos de Acaz (2 Cr 28:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81656, 'spa', 'Ciudad portuaria de Eilat', 'La ciudad portuaria de Eilat/Elat en el golfo de Áqaba. Israel pasó cerca de ella durante las peregrinaciones por el desierto (Dt 2:8), y posteriormente se convirtió en un codiciado puerto: Azarías (Uzías) la reconstruyó para Judá (2 R 14:22), pero el rey arameo Rezín la arrebató de nuevo (2 R 16:6). Todas las traducciones principales transliteran el nombre con mínima variación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81657, 'spa', 'Ciudad portuaria de Elot', 'La ciudad portuaria de Elot, idéntica a Eilat, en el golfo de Áqaba. Salomón estableció allí su flota mercante (1 R 9:26; 2 Cr 8:17), y Uzías la restauró para Judá posteriormente (2 Cr 26:2). Las traducciones oscilan entre ''Eilat'' y ''Elot'', confirmando que ambas grafías se refieren al mismo puerto estratégico en el brazo oriental del mar Rojo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81659, 'spa', 'Pórtico cubierto o vestíbulo que precede a cada complejo de puertas y al santuar', 'Pórtico cubierto o vestíbulo que precede a cada complejo de puertas y al santuario interior en la visión del templo de Ezequiel (Ez 40-41). Variante del más común ulam, este término se limita enteramente a las mediciones arquitectónicas de Ezequiel, donde el guía angélico registra las dimensiones del pórtico de cada puerta — este (Ez 40:16, 21-22), norte (Ez 40:24-26), sur (Ez 40:29-31, 33-34) — y del vestíbulo del templo interior (Ez 40:48-49; 41:15, 25-26). Su significado queda fijado por el contexto: una entrada techada con columnas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81664, 'spa', 'Elim (topónimo)', 'Elim (אֵילִם, ''terebintos'' o ''árboles grandes''), el campamento-oasis donde Israel descansó después de Mara. Sus doce fuentes y setenta palmeras se registran en Éx 15:27 y en el itinerario de Núm 33:9-10. La partida hacia el desierto de Sin se menciona en Éx 16:1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81668, 'spa', 'El árbol', 'Árbol (arameo אִילָן), empleado en Daniel 4 para el enorme árbol del sueño de Nabucodonosor. Crece hasta el cielo, visible en toda la tierra, proveyendo alimento y refugio a las criaturas (Dan 4:10-11). Simboliza el reino del rey, y la orden de talarlo representa su humillación divina (Dan 4:14, 20, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81671, 'spa', 'Cierva grácil', 'El título del Salmo 22, «La cierva del alba» (probablemente un nombre de melodía), evoca a esta criatura elegante. Proverbios 5:19 compara el amor de la esposa con la ternura de la cierva: suave, leal y reconfortante. Jeremías 14:5 intensifica el horror de la sequía al describir cómo hasta la cierva abandona a su cervatillo por falta de pasto. Sus asociaciones —belleza, devoción, instinto maternal y agilidad en las montañas— la convirtieron en rico recurso poético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81672, 'spa', 'Sobrecogedor y temible', 'Cantar de los Cantares 6:4 y 6:10 describen a la amada como «imponente cual ejércitos abanderados»; su belleza impone la clase de temor reverente que inspiran los ejércitos. Habacuc 1:7 retrata a los caldeos como «terribles y temibles», un pueblo cuya autoridad autoproclamada y feroz reputación los precede. La raíz hebrea sugiere causar estremecimiento, ya sea por una belleza que abruma, un poderío militar que aterra, o una dignidad que impone.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81673, 'spa', 'La emocion abstracta de terror, pavor o miedo paralizante', 'La emocion abstracta de terror, pavor o miedo paralizante. Se usa para el pavor divino que cae sobre las naciones (Exod 15:16, emparejado con pakhad; Exod 23:27), la angustia existencial (Gen 15:12, ''pavor y gran oscuridad''), el miedo a los enemigos (Jos 2:9; Isa 33:18), el terror de la muerte (Sal 55:4-5) y el temor reverencial inspirado por el poder real (Prov 20:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81686, 'spa', 'Objetos concretos de terror', 'Objetos concretos de terror: imagenes espantosas o idolos que inspiran pavor. En Jeremias 50:38, la evidencia multilingue apunta lejos del miedo abstracto: se traduce como ''imagenes horribles'' o ''idolos'' en un contexto que describe objetos culticos de Babilonia. Este sentido probablemente se refiere a las figuras talladas aterradoras del culto babilonico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81689, 'spa', 'Pueblo gigante preisraelita', 'Génesis 14:5 menciona a los emim entre los pueblos derrotados por la coalición de Quedorlaomer al este del Jordán. Deuteronomio 2:10-11 explica que los moabitas los llamaban emim, aunque eran ''un pueblo grande, numeroso y de alta estatura como los anaceos'', ambos considerados refaítas. El nombre ''terrores'' capta su presencia intimidante, pero el texto recuerda a Israel que Dios permitió incluso a pueblos más pequeños vencerlos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81690, 'spa', 'negación existencial: no hay', 'La negación existencial central: ''no hay, no existe, no está presente''. Este grupo masivo de 738 ocurrencias abarca todas las formas flexionadas con sufijos pronominales y con o sin waw conjuntiva. Funciona como el negador estándar de existencia y presencia a lo largo de toda la Biblia hebrea. José dice a Faraón: ''no hay quien lo interprete'' (Gn 41:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81694, 'spa', 'privativo: sin, a falta de', 'Sentido preposicional privativo: ''sin, por falta de, en ausencia de''. Treinta y siete ocurrencias, generalmente con prefijo מִן (מֵאַיִן), בְּ (בְּאֵין) o לְ (לְאֵין), formando preposiciones compuestas que significan ''sin''. Éxodo 21:11 estipula que la esclava puede salir libre ''sin pago''; Nehemías exhorta al pueblo a compartir con quienes ''no tienen nada preparado'' (Neh 8:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81700, 'spa', 'negación verbal simple', 'Negación verbal simple en contextos retóricos o condicionales: 9 ocurrencias donde אֵין funciona como negador escueto (''no'') sin expresar propiamente inexistencia. Moisés pregunta en Masá: ''¿Está el Señor entre nosotros o no?'' (Éx 17:7); los espías deben evaluar la tierra: ''si hay árboles en ella o no'' (Nm 13:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81708, 'spa', 'sustantival: nada, como nada', 'Uso sustantival o comparativo: ''nada, como nada''. Seis ocurrencias donde אַיִן funciona como sustantivo o en la construcción comparativa כְּאַיִן (''como nada''). Isaías 40:17 declara que ''todas las naciones son como nada ante él''; Salmo 39:5 lamenta que todo hombre en pie es ''del todo como nada''; Hageo 2:3 pregunta sobre la gloria del templo: ''¿no es como nada a vuestros ojos?''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81773, 'spa', 'Adverbio interrogativo que pregunta por el origen o la procedencia', 'Adverbio interrogativo que pregunta por el origen o la procedencia: ''¿de donde?'' Se usa tanto en indagaciones practicas sobre la patria de una persona (Gen 29:4; Gen 42:7; Jue 17:9; 19:17) como en preguntas retoricas o poeticas elevadas que sondean realidades mas profundas: la exasperacion de Moises ''¿De donde voy a sacar carne?'' (Num 11:13), la profunda pregunta de Job ''¿De donde viene la sabiduria?'' (Job 28:12, 20) y la confianza del salmista ''¿De donde vendra mi socorro?'' (Sal 121:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81778, 'spa', 'efa (medida de áridos)', 'efa (medida de áridos)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81790, 'spa', '¿Dónde? (interrogativo de lugar) — Adverbio interrogativo que significa ''¿dónde?', '¿Dónde? (interrogativo de lugar) — Adverbio interrogativo que significa ''¿dónde?'', usado para preguntar por una ubicación, a menudo con una carga narrativa o teológica que trasciende la pregunta literal. José lo emplea para buscar el paradero de sus hermanos (Gn 37:16), Noemí lo usa para descubrir al benefactor de Rut (Rt 2:19), y Dios lo despliega como arma retórica devastadora contra Job (Job 38:4). También aparece en Isaías 49:21 y Jueces 8:18. El componente אֵי (''¿dónde?'') se combina con la partícula enclítica פֹה (''aquí'') para enfatizar la inmediatez de la pregunta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81792, 'spa', 'hombre, varón, persona', 'El sentido primario: un hombre, persona masculina, individuo humano — 2.130 ocurrencias que abarcan narrativa, legislación, poesía y profecía. Cubre individuos con nombre (''el varón Moisés''), referencias genéricas (''si un hombre hace...''), designaciones colectivas (''los hombres de Israel'') y cadenas constructas de función social (''hombres de valor'', ''hombres de la ciudad'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81806, 'spa', 'esposo, marido', 'Esposo, cónyuge — 42 ocurrencias donde אִישׁ designa específicamente al compañero matrimonial de una mujer. Aparece típicamente con sufijos posesivos femeninos: אִישָׁהּ (''su marido'', Gn 3:16; 16:3) o en contextos maritales explícitos como el ritual de la sospechosa de adulterio (Nm 5:19-20). Las lenguas seleccionan vocabulario dedicado: marido/esposo (esp.), mari (fr.), Ehemann (al.).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81839, 'spa', 'cada uno (distributivo)', 'Pronombre distributivo: cada uno, todos, cualquiera, nadie — 13 ocurrencias donde אִישׁ funciona no como sustantivo que designa a un varón específico, sino como pronombre indefinido o distributivo. ''Ponga cada uno su espada al lado'' (Éx 32:27), ''que nadie se ponga sus adornos'' (Éx 33:4). Este uso pronominal, frecuente en la fórmula אִישׁ...אִישׁ (''cada uno... cada uno''), es un rasgo característicamente semítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81861, 'spa', 'macho (de animales)', 'Macho (de animales o en contextos de clasificación por sexo) — 2 ocurrencias en Gn 7:2, donde se instruye a Noé a tomar animales ''macho y su pareja''. Aquí אִישׁ designa el sexo biológico en vez de la condición de persona humana, emparejado con אִשְׁתּוֹ (''su hembra/pareja''). El paso del sentido de persona al de sexo biológico se confirma interlingüísticamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81882, 'spa', 'Nombre propio masculino Is-boset, referido exclusivamente al hijo de Saúl que re', 'Nombre propio masculino Is-boset, referido exclusivamente al hijo de Saúl que reinó sobre Israel en oposición a David (2 Samuel 2-4). Los componentes del nombre — ish (''hombre'') y bosheth (''vergüenza'') — representan una enmienda teológica del original Ish-Baal, como lo confirma el paralelo del Cronista con Esbaal (1 Cr 8:33; 9:39). Las 22 ocurrencias se concentran en 2 Samuel 2-4, narrando su instalación como rey por Abner, su débil gobierno, y su asesinato a manos de Recab y Baana, lo cual despejó el camino para la monarquía unida de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81886, 'spa', 'Pupila del ojo', 'La pupila del ojo, el centro oscuro que refleja una imagen diminuta del observador. Se usa en contextos figurativos de algo precioso: Dios guardó a Israel ''como la niña de su ojo'' (Dt 32:10), el salmista suplica protección (Sal 17:8), y el sabio exhorta a guardar la sabiduría así (Pr 7:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81888, 'spa', 'Oscuridad de la noche', 'La parte más negra de la noche, extendiendo la imagen de la ''pupila'' a la oscuridad temporal. En Pr 7:9, el joven encuentra a la adúltera ''en la pupila de la noche'' (בְּאִישׁוֹן לַיְלָה), y en Pr 20:20, la lámpara del hijo rebelde se apaga ''en la pupila de las tinieblas'' (בֶּאֱשׁוּן חֹשֶׁךְ).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81892, 'spa', 'Particula existencial aramea que afirma que algo existe o esta presente, equival', 'Particula existencial aramea que afirma que algo existe o esta presente, equivalente al hebreo yēsh. En uso absoluto declara existencia: ''hay un Dios en el cielo'' (Dan 2:28). Con sufijos pronominales se vuelve copulativa: ''¿eres tu capaz?'' (Dan 2:26), ''no estamos dispuestos'' (Dan 3:18). Se encuentra unicamente en las porciones arameas de Esdras y Daniel. Las formas cognadas en siriaco, palmireno y mandeo confirman su estatus panarameico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81899, 'spa', 'Nombre propio ambiguo', 'Nehemías 11:7 enumera a Itiel en una genealogía de residentes benjamitas en Jerusalén. Proverbios 30:1 presenta el enigma: ''el oráculo del hombre a Itiel, a Itiel y a Ucal'' en la lectura tradicional, aunque muchas traducciones modernas adoptan la enmienda que lo interpreta como una confesión de cansancio y no como el nombre de un destinatario. Las glosas multilingües reflejan esta ambigüedad textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81900, 'spa', 'Nombre propio de Itamar, el hijo menor de Aarón, quien asumió responsabilidades ', 'Nombre propio de Itamar, el hijo menor de Aarón, quien asumió responsabilidades sacerdotales tras la muerte de Nadab y Abiú (Lv 10:6, 12). Supervisó las tareas de transporte de los gersonitas y meraritas (Nm 4:28, 33), y su línea continuó a través de Elí. Se traduce de manera uniforme en todas las tradiciones: ''Itamar'' en español, ''Ithamar'' en inglés y alemán, reflejando una transliteración estable del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81904, 'spa', 'Duradero, firme, permanente — Fuerte, firme, duradero, permanente en sentido adj', 'Duradero, firme, permanente — Fuerte, firme, duradero, permanente en sentido adjetival general. Aplicado a una nación antigua y poderosa (Jer 5:15), a un nido asentado en la roca que parece inexpugnable (Nm 24:21) y a un sufrimiento descrito como duro o constante (Job 33:19). Proverbios 13:15 extiende el sentido a lo que es difícil o intratable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81906, 'spa', 'Perenne, que fluye siempre — Describe un arroyo o wadi que no se seca en verano', 'Perenne, que fluye siempre — Describe un arroyo o wadi que no se seca en verano. En Dt 21:4, el ritual de la becerra requiere un נַחַל אֵיתָן, un wadi con agua corriente, y Sal 74:15 habla de ríos de flujo constante. El uso más célebre es Amós 5:24, donde la justicia debe ser como un arroyo que no se seca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81907, 'spa', 'Los perdurables, los poderosos — Usado como sustantivo para designar cimientos p', 'Los perdurables, los poderosos — Usado como sustantivo para designar cimientos perdurables o personas poderosas. En Job 12:19 Dios lleva cautivos a ''los poderosos'', despojando el poder establecido; en Mi 6:2 los montes y los cimientos perdurables de la tierra son llamados a escuchar el pleito de Dios. La forma plural אֵיתָנִים pasa de describir una cualidad a nombrar a quienes la poseen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81910, 'spa', 'Fuerza, firmeza — Sentido de sustantivo abstracto que significa fuerza o firmeza', 'Fuerza, firmeza — Sentido de sustantivo abstracto que significa fuerza o firmeza, típicamente regido por una preposición. En Gn 49:24, el arco de José permanece בְּאֵיתָן (''en firmeza''), describiendo el poder resiliente de sus brazos. En Éx 14:27, el mar vuelve לְאֵיתָנוֹ (''a su fuerza normal''), cuando las aguas retornan a su estado natural y constante tras el cruce.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81916, 'spa', 'Etán (nombre propio)', 'Nombre propio masculino Etán (אֵיתָן como nombre personal, distinto del adjetivo común que significa ''perdurable''), referido principalmente a Etán el ezraíta, célebre por una sabiduría que rivalizaba con la de Salomón (1 Re 4:31) y mencionado en el encabezado del Salmo 89. En las genealogías del Cronista aparece entre los hijos de Zéraj (1 Cr 2:6, 8) e identificado como cantor levítico junto a Hemán y Asaf.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81921, 'spa', 'solo, solamente (restrictiva)', 'Sentido restrictivo: ''solo, solamente, nada más que''. Limita el alcance de lo que sigue, marcando una excepción o condición. En Éx 12:16 no se hará trabajo alguno, ''solo lo que cada persona haya de comer, eso solo se preparará''. El alemán nur y el español solamente expresan con precisión esta función limitativa. La partícula estrecha el campo de posibilidades, funcionando como el inglés only o just.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81922, 'spa', 'ciertamente (aseverativa)', 'Sentido aseverativo: ''ciertamente, en verdad, sin duda''. Introduce una afirmación enfática, a menudo marcando el descubrimiento repentino o la aserción confiada del hablante. ''¡Ciertamente hueso mío y carne mía eres!'' de Labán (Gn 29:14); ''¡Ciertamente el ungido de Jehová está delante de él!'' de Samuel (1 S 16:6). El francés certes y el alemán fürwahr captan esta certeza enfática. Frecuente en discurso coloquial y emocionalmente cargado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81923, 'spa', 'pero, sin embargo (adversativa)', 'Sentido adversativo: ''pero, sin embargo, no obstante''. Introduce un contraste, matización o concesión frente a lo precedente. En Gn 9:4, tras conceder permiso para comer carne: ''pero carne con su vida, su sangre, no comeréis''. En Gn 20:12, Abraham matiza: ''pero en verdad ella es mi hermana''. El español pero/sin embargo y el alemán aber expresan claramente este giro contrastivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81959, 'spa', 'Dos ciudades de Aczib', 'Dos ciudades llamadas Aczib. La Aczib de Judá aparece en Jos 15:44 y Mi 1:14, donde Miqueas explota su etimología con un juego de palabras sobre el ''engaño'' (cf. la raíz relacionada כ-ז-ב). La Aczib de Aser, en la costa fenicia (Jos 19:29; Jue 1:31), era una ciudad cananea que los israelitas no lograron desposeer. Las traducciones transliteran uniformemente el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81960, 'spa', 'Cruel, feroz', 'Cruel o feroz en un sentido visceral e implacable. Se aplica al veneno de las cobras como ''ponzoña feroz'' (Dt 32:33), a la naturaleza aterradora del Leviatán que hace retroceder a cualquier retador (Job 41:10), y de manera sustantivada a Dios mismo cuando Job protesta que el Todopoderoso se ha convertido en ''uno cruel'' hacia él (Job 30:21). En Lm 4:3 el profeta compara a las hijas de su pueblo con avestruces, crueles por abandono.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81961, 'spa', 'Cruel, feroz (adjetivo)', 'El adjetivo אַכְזָרִי describe a una persona, fuerza o cualidad como cruel, feroz o despiadada. En la literatura sapiencial caracteriza a amos implacables (Prov 5:9), la falsa compasión de los impíos (Prov 12:10) y al mensajero despiadado enviado contra los rebeldes (Prov 17:11). Proféticamente, Jeremías lo aplica a los invasores babilonios —un pueblo ''cruel y sin misericordia'' (Jer 6:23; 50:42).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81967, 'spa', 'Nombre propio del rey filisteo de Gat, figura central en el relato del exilio de', 'Nombre propio del rey filisteo de Gat, figura central en el relato del exilio de David durante su huida de Saúl. David fingió locura ante él (1 S 21:11-15) y más tarde buscó asilo, recibiendo Siclag (1 S 27:2-6). Un segundo Aquis aparece en la era de Salomón (1 R 2:39-40). Se translitéra de forma consistente en las distintas lenguas: ''Achish'' en inglés, ''Aquis'' en español.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81968, 'spa', 'comer (ingerir alimento)', 'El sentido básico del Qal: comer literalmente, ingestión física de alimento en cualquier tiempo, persona o número. Este sentido abrumadoramente dominante (697 ocurrencias) abarca desde comidas ordinarias hasta actos teológicamente cargados: el fruto prohibido (Gn 3:6), el cordero pascual (Éx 12:11), el maná en el desierto (Éx 16:35) y las porciones sacerdotales (Lv 6:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81986, 'spa', 'ser comido (pasivo)', 'El Nifal pasivo: ser comido, ser consumido o estar permitido para el consumo — 36 ocurrencias concentradas en la legislación legal y cultual. Éxodo 12:46 estipula que el cordero pascual ''será comido en una sola casa''; Levítico especifica repetidamente qué porciones sacrificiales ''serán comidas'' y por quién (Lv 6:16, 23, 26; 7:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (81989, 'spa', 'devorar (consumir destructivamente)', 'Devoración o consumo destructivo figurado — 75 ocurrencias donde el agente que ''come'' es fuego, espada, plaga o juicio, no una persona a la mesa. Dios aparece como ''fuego consumidor'' en el Sinaí (Éx 24:17; Dt 4:24; 9:3), el fuego de Hesbón ''devoró'' a Moab (Nm 21:28), y las naciones ''consumen'' a Israel (Lv 26:38). El español distingue claramente con devorar y consumir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82057, 'spa', 'alimentar (dar de comer)', 'El Hifil causativo: alimentar, dar de comer, proveer alimento a otro — solo 6 ocurrencias pero de gran peso teológico. Dios ''alimentó'' a Israel con maná (Dt 8:3, 16; Éx 16:32), y el pueblo recuerda la carne que Dios ''les dio de comer'' (Nm 11:4, 18). El español alimentar y dar de comer seleccionan vocabulario causativo dedicado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82115, 'spa', 'consumirse (zarza ardiente)', 'Una sola ocurrencia en Éxodo 3:2, donde la zarza ardiente ''no se consumía'': Moisés ve que el fuego arde pero la zarza no es ''comida''. La evidencia de las traducciones (consumida en esp., verzehrte en al., consuma en fr.) sitúa este caso en la intersección de los sentidos 1 y 2, combinando la metáfora de consumo por fuego con un matiz estativo o resultativo de singularidad teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82140, 'spa', 'Comer, devorar', 'Comer o devorar, literal y en imágenes apocalípticas. En Dn 4:33, el humillado Nabucodonosor come hierba como un buey, señal vívida del juicio divino que reduce a un rey a existencia bestial. Las bestias apocalípticas de Daniel 7 devoran carne y pisotean restos (7:5, 7, 19), culminando en la cuarta bestia que ''devorará toda la tierra'' (7:23), metáfora de la conquista imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82141, 'spa', 'Acusar, calumniar', 'Acusar o calumniar, según el modismo arameo akal qartsehon (''comer sus pedazos/bocados''). Esta expresión vívida —que evoca quizás la imagen de despedazar la reputación de alguien y consumirla— describe la denuncia maliciosa ante un rey. En Dn 3:8, funcionarios caldeos ''comieron los pedazos de'' los tres jóvenes judíos, acusándolos de negarse a adorar la imagen de oro. En Dn 6:24 se usa la misma expresión contra Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82146, 'spa', 'alimento, sustento — Alimento como sustancia', 'alimento, sustento — Alimento como sustancia: provisiones, sustento o suministro alimenticio, ya sea grano almacenado, raciones compradas o sustento dado por Dios. Este es el sentido dominante en la narrativa de José (Gn 41:35-36, 48; 42:7, 10, 33; 43:2, 4, 20, 22; 44:1-2, 25) y en contextos cúlticos donde las ofrendas se convierten en ''alimento'' sobre el altar (Mal 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82149, 'spa', 'comer, acto de comer — El acto o proceso de comer, funcionando como sustantivo v', 'comer, acto de comer — El acto o proceso de comer, funcionando como sustantivo verbal que nombra la actividad misma en lugar de la sustancia. Rut llega ''a la hora de comer'' (Rut 2:14), cada israelita recoge maná ''conforme a lo que come'' (Éx 16:16, 18, 21), y el cordero pascual se distribuye ''conforme a lo que cada uno come'' (Éx 12:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82153, 'spa', 'presa, alimento del depredador — Presa o alimento arrebatado por un depredador', 'presa, alimento del depredador — Presa o alimento arrebatado por un depredador: un solo uso vívido en Job 9:26 que compara los días fugaces con un águila que ''se lanza sobre la presa''. La metáfora traslada la palabra de la mesa doméstica a la caza salvaje, enfatizando velocidad y voracidad en lugar de nutrición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82161, 'spa', 'Alimento, sustento o provision designada para el consumo de los seres vivos', 'Alimento, sustento o provision designada para el consumo de los seres vivos. Las catorce ocurrencias aparecen en la formula le''okhlah (''para comida''), comenzando con la creacion misma: Dios da toda planta que da semilla y todo arbol frutal a la humanidad y a los animales para alimento (Gen 1:29-30). La formula se repite en las provisiones para el arca (Gen 6:21) y el pacto posterior al diluvio (Gen 9:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82163, 'spa', 'Presa, combustible o material entregado al consumo devorador o a la destruccion', 'Presa, combustible o material entregado al consumo devorador o a la destruccion: una extension metaforica de ''alimento''. Ezequiel usa le''okhlah cuatro veces en oraculos de juicio profetico: madera de vid arrojada al fuego como combustible (Ezeq 15:4, 6), la espada del juicio divino que ''devora'' (Ezeq 21:32) y ninos sacrificados como ofrendas ''para consumir'' (Ezeq 23:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82168, 'spa', 'Particula aseverativa enfatica que significa ''ciertamente, verdaderamente, en ve', 'Particula aseverativa enfatica que significa ''ciertamente, verdaderamente, en verdad'', afirmando la realidad o verdad de una declaracion con fuerte conviccion. Este sentido dominante cubre dieciseis de dieciocho ocurrencias y frecuentemente marca un momento de revelacion o declaracion solemne. Jacob despierta y dice ''Ciertamente el SENOR esta en este lugar'' (Gen 28:16); Moises comprende ''Ciertamente el asunto se ha sabido'' (Exod 2:14); Isaias proclama verdades teologicas profundas (Isa 45:15; 53:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82170, 'spa', 'Particula adversativa o contrastiva que significa ''pero, sin embargo, no obstant', 'Particula adversativa o contrastiva que significa ''pero, sin embargo, no obstante'', introduciendo una declaracion contraria a lo esperado. En Salmo 82:7, tras la interpelacion divina a los ''dioses'', ''aken gira abruptamente: ''pero morireis como mortales''. En Sofonias 3:7, Dios esperaba que la ciudad aceptara correccion, ''pero'' (''aken) se apresuraron a corromper todas sus obras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82177, 'spa', 'Labrador, agricultor', 'Agricultor, labrador o trabajador agrícola que cultiva la tierra, mencionado frecuentemente junto a los viñadores como representante de la columna vertebral de la economía agraria (2 Cr 26:10; Jl 1:11). Jeremías retrata su desesperación durante la sequía (Jer 14:4) y su futura restauración (Jer 31:24), mientras Isaías profetiza que extranjeros servirán como labradores de Israel (Is 61:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82180, 'spa', 'Ciudad cananea norteña', 'Josué 11:1 incluye al rey de Acsaf entre la coalición norteña que se congregó para combatir a Israel en las aguas de Merom. Josué 12:20 registra la derrota de su rey en el catálogo de ciudades conquistadas. Josué 19:25 asigna Acsaf al territorio fronterizo de Aser. La evidencia arqueológica y lingüística señala una ciudad importante que controlaba territorio en el norte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82181, 'spa', 'negación prohibitiva: ¡no!', 'El uso prohibitivo o vetitivo dominante, emparejado con imperfectos yusivos y cohortativos para expresar mandatos negativos, ruegos y deseos: ''¡no hagas!'', ''¡que no sea!'' (712 de 725 ocurrencias). Presente en todos los géneros: la seguridad patriarcal (Gn 15:1 אַל־תִּירָא), la atadura de Isaac (Gn 22:12 אַל־תִּשְׁלַח יָדְךָ) y la petición sálmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82193, 'spa', 'respuesta negativa: no', 'Respuesta negativa independiente o negación existencial que significa ''no'' o ''no hay'', con función declarativa en lugar de prohibitiva. En Rut 1:13 Noemí dice אַל בְּנֹתַי, un sentido ''no, hijas mías''; en 2 Samuel 1:21 el lamento de David lo emplea para la ausencia existencial. Las traducciones confirman el paso de la prohibición a la negación rotunda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82197, 'spa', 'negación retórico-interrogativa', 'Uso retórico-interrogativo poco frecuente donde אַל introduce una pregunta que espera respuesta afirmativa, funcionando como ''¿acaso no...?'' o ''¿dónde?''. En 1 Samuel 27:10, la respuesta evasiva de David a Aquis emplea esta construcción. Las traducciones muestran un sentido interrogativo espacial más que una simple negación, reflejando la dependencia contextual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82199, 'spa', 'sustantival: nada, en vano', 'Uso sustantival hapax en Job 24:25, donde אַל con preposición transmite ''a nada'' o ''en vano'', expresando futilidad o ausencia total de sustancia. El español en nada y el francés à ne...pas captan este desplazamiento de partícula a cuasi-sustantivo, propio del registro poético elevado de Job.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82203, 'spa', 'Prohibición aramea', 'Partícula aramea de prohibición que significa ''no'' o ''que no'', que rige un verbo en imperfecto. Daniel la emplea con urgencia: ''no destruyas a los sabios'' (Dn 2:24), y reaparece en expresiones de consuelo: ''que no te alarme el sueño'' (Dn 4:19), ''que no te aterroricen tus pensamientos'' (Dn 5:10). Funciona como equivalente directo del hebreo אַל en los pasajes arameos del libro de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82204, 'spa', 'Dios, el Dios verdadero', 'El Dios verdadero de Israel, empleado como nombre o título divino en 223 de 245 ocurrencias. Abarca אֵל como designación divina independiente en poesía (Sal 18:31, ''¿Quién es אֵל fuera de YHWH?''), en epítetos compuestos (El Shaddai, Gn 17:1; El Elyon, Gn 14:18; El Olam, Gn 21:33; El Betel, Gn 35:7), con sufijos posesivos (''mi Dios'', ''tu Dios'') y en construcciones atributivas (''Dios celoso'', ''Dios misericordioso'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82224, 'spa', 'poderoso, poder', 'Fuerza, poder o capacidad: un uso sustantival o adjetival no divino que significa ''fortaleza'' o ''en poder de'', con 10 ocurrencias. Labán dice a Jacob ''está en el poder de mi mano'' (לְאֵל יָדִי, Gn 31:29); Deuteronomio advierte ''no habrá poder en tu mano'' (Dt 28:32). En Sal 29:1 los בְּנֵי אֵלִים son ''hijos de poder'' (seres celestiales). El español poder capta este sentido no teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82228, 'spa', 'un dios, deidad (genérico)', 'Un dios o deidad en sentido genérico, con 9 ocurrencias referidas a dioses extranjeros, falsas deidades o el concepto abstracto de divinidad. La pregunta retórica ''¿Quién como tú entre los dioses?'' (Éx 15:11) y la advertencia contra un ''dios extraño'' (Sal 81:9) usan אֵל sin referencia específica a YHWH. Dt 32:12 declara ''ningún אֵל extranjero estaba con él'', y Dt 32:21 habla de provocar a Dios con ''un no-dios''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82236, 'spa', 'El (en nombres propios)', 'El elemento teofórico אֵל como componente de nombres propios o designador nominal independiente, con 2 ocurrencias donde funciona como parte de un nombre personal o cúltico en vez de sustantivo común o título divino. En Jue 9:46, la ''casa de El-Berit'' nombra a una deidad cananea específica; en 2 S 2:30, ''Asael'' incluye אֵל como elemento onomástico. El español, francés y alemán transliteran en lugar de traducir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82253, 'spa', 'encina, árbol grande', 'Una única ocurrencia en Is 57:5 donde אֵל aparece en la frase ''debajo de todo árbol frondoso'', tradicionalmente vertida como ''entre las encinas'' o ''entre los terebintos'', posiblemente reflejando una raíz homónima que significa ''encina'' o ''árbol grande'' (cf. hebreo אֵלָה, אַלָּה). La evidencia multilingüe se divide: el español ''entre las encinas'' lo trata como término arbóreo, mientras el francés Dieu y el alemán Gott lo leen como vocablo divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82259, 'spa', 'Estos, estas (demostrativo)', 'Pronombre demostrativo plural que significa ''estos/estas'', variante ortográfica de אֵלֶּה empleada en textos pentateúquicos e históricos. En Gn 19:8, Lot ofrece ''estas dos hijas''; en Gn 26:3-4, Dios confirma a Isaac ''todas estas tierras''; en Lv 18:27, se refiere a las abominaciones que ''estos'' cananeos cometieron; y en Dt 4:42 y 19:11, designa ''estas ciudades'' de refugio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82262, 'spa', 'direccional: a, hacia', 'Sentido direccional primario en contextos de division textual: ''a'' o ''hacia'' una persona, lugar o cosa. Funciona como la acepcion base de la preposicion, siguiendo a todo verbo de movimiento y discurso para marcar destino o destinatario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82273, 'spa', 'dentro de, al interior', 'Movimiento hacia un espacio cerrado o interior: ''dentro de'' mas que simplemente ''hacia''. Deuteronomio 31:7 envia a Josue ''dentro de'' la tierra que Dios prometio. El punto final espacial no es una superficie sino un interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82283, 'spa', 'sobre, encima de', 'Contacto o posicion sobre una superficie, o autoridad puesta sobre alguien: ''sobre, encima de''. Numeros 4:19 asigna a los levitas ''a'' su servicio. 2 Samuel 2:9 coloca a Is-boset ''sobre'' Galaad. En oraculos profeticos la preposicion desliza de ''hacia'' a ''sobre/contra''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82298, 'spa', 'por, acerca de', 'Proposito, beneficio o referencia: ''por, acerca de''. 1 Samuel 1:27 habla de orar ''por'' este nino. 1 Samuel 15:35 registra el duelo de Samuel ''por'' Saul. La metafora direccional se extiende: la atencion del hablante se dirige ''hacia'' un tema o causa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82301, 'spa', 'contra, en oposicion', 'Orientacion hostil o adversativa: ''contra''. Genesis 4:8 presenta a Cain levantandose ''contra'' su hermano Abel. Deuteronomio 28:7 promete que los enemigos que se levanten ''contra'' Israel seran derrotados. El nucleo direccional adquiere un matiz adversativo por el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82306, 'spa', 'con, entre', 'Compania o proximidad: ''con, entre, junto a''. Numeros 23:4,16 describen a Dios encontrandose ''con'' Balaam. Josue 11:19 senala que ninguna ciudad hizo paz ''con'' Israel. La preposicion marca no solo movimiento hacia sino llegada y permanencia junto a alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82319, 'spa', 'ante, delante de', 'Sentido raro atestiguado una vez en el Salmo 84:7, donde el texto masoretico ubica la preposicion de manera inusual. La evidencia multilingue diverge: ''ante'', ''delante de''. Sugiere comparecer en la presencia de Dios, posiblemente un uso liturgico de avanzar ''hacia'' Dios hasta estar ''ante'' el en Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82324, 'spa', 'Granizo como juicio', 'Ezequiel 13:11 y 13:13 advierten a los falsos profetas que Dios derribará su muro blanqueado con ''grandes piedras de granizo'' que destruyen la pretensión y exponen la falsedad. Ezequiel 38:22 describe a Dios haciendo llover granizo sobre Gog y sus hordas, combinando pestilencia, sangre, lluvia torrencial y granizo en una demostración de poder soberano. La conexión del término hebreo con materiales pétreos enfatiza la fuerza destructiva del granizo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82325, 'spa', 'Madera preciosa importada', '2 Crónicas 2:8 solicita madera de algum del Líbano junto con cedros y cipreses para el templo. 2 Crónicas 9:10-11 describe las naves de Hiram trayendo madera de algum desde Ofir, que Salomón utilizó para construir escalinatas del templo y el palacio, así como liras y arpas para los músicos. El valor de esta madera se subraya por su asociación con piedras preciosas y su uso tanto en la arquitectura sagrada como en instrumentos musicales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82329, 'spa', 'Jurar, conjurar', 'Hacer un juramento solemne ante Dios, o (en Hifil) conjurar, poner a otro bajo juramento. Saúl conjuró al ejército con un juramento de ayuno (1 S 14:24), la dedicación del templo contempla el juramento ante el altar (1 R 8:31), y Oseas denuncia los falsos juramentos de Israel (Os 4:2; 10:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82334, 'spa', 'Maldecir, imprecar', 'Maldecir, proferir una imprecación contra alguien. En Jue 17:2, la madre de Micaía pronunció una maldición sobre quien robó su plata (אָלִית, ''maldijiste''), y la narrativa gira en torno al poder de esa imprecación. A diferencia del sentido 1, el acto de habla es hostil y dirigido contra una persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82335, 'spa', 'juramento, pacto jurado — Juramento solemne o compromiso pactual jurado, que típ', 'juramento, pacto jurado — Juramento solemne o compromiso pactual jurado, que típicamente conlleva un elemento autoimprecatorio implícito que vincula al jurador a consecuencias si lo viola. Diecisiete ocurrencias enfatizan la dimensión de juramento-pacto: el juramento que asegura la misión del siervo de Abraham (Gn 24:41), el pacto jurado en Beerseba (Gn 26:28) y el juramento ligado a la entrada al pacto mosaico (Dt 29:12, 14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82336, 'spa', 'maldición, imprecación — Maldición o imprecación', 'maldición, imprecación — Maldición o imprecación: la automaldición condicional invocada ante el quebrantamiento de un juramento, o un pronunciamiento directo de juicio divino contra los transgresores. Dieciocho ocurrencias se centran en la dimensión de maldición: las aguas de maldición en la ordalia de la sospechosa de adulterio (Nm 5:21-27), las maldiciones del pacto en Deuteronomio (Dt 29:19-20) y el rollo volante de Zacarías (Zac 5:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82343, 'spa', 'adjurar, hacer jurar (Hifil) — Adjurar o hacer jurar', 'adjurar, hacer jurar (Hifil) — Adjurar o hacer jurar: el uso verbal causativo en Hifil, que pone a alguien bajo juramento invocando la maldición condicional. Solo una ocurrencia clara: la oración de Salomón en la que un hombre peca contra su prójimo y ''se le impone juramento para hacerle jurar'' (2 Cr 6:22, paralelo a 1 R 8:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82357, 'spa', 'Terebinto, encina — Árbol grande y longevo (Pistacia terebinthus o posiblemente ', 'Terebinto, encina — Árbol grande y longevo (Pistacia terebinthus o posiblemente especies de Quercus) que servía como punto de referencia reconocible y lugar de reunión en el paisaje del antiguo Israel. Ejemplares notables marcan momentos narrativos clave: el entierro de dioses extranjeros por Jacob en Siquem (Gn 35:4), la aparición del ángel a Gedeón en Ofrá (Jue 6:11, 19), el memorial funerario de Saúl en Jabés (1 Cr 10:12) y el árbol donde Absalón quedó atrapado (2 S 18:9-14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82363, 'spa', 'Nombre propio Ela (אֵלָה II, ''terebinto''), referido a multiples individuos del A', 'Nombre propio Ela (אֵלָה II, ''terebinto''), referido a multiples individuos del AT: (1) un jefe de Edom listado entre los descendientes de Esau (Gen 36:41; 1 Cro 1:52); (2) el hijo de Baasa que reino dos anos en Israel antes del golpe de Zimri (1 Rey 16:6, 8, 13-14); (3) el padre de Oseas, ultimo rey de Israel (2 Rey 15:30; 17:1); (4) un hijo de Caleb (1 Cro 4:15); (5) un benjaminita del linaje de Uzi (1 Cro 9:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82366, 'spa', 'Dios, el Dios verdadero', 'Dios, el Dios verdadero. El Dios de Israel, la deidad suprema y verdadera adorada por Daniel, Esdras y los exiliados judios. Aparece en formas definidas, constructas y con sufijos. Esdras habla del ''Dios del cielo'' que movio a Ciro (Esd 5:1), y el Dios de Daniel lo libra del foso de los leones (Dan 6:23). El espanol Dios, el frances Dieu y el aleman Gott lo traducen uniformemente como referencia al unico Dios verdadero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82367, 'spa', 'dios(es), deidades paganas', 'dios(es), deidades paganas. Un dios o dioses en sentido generico o pagano -- falsas deidades adoradas por naciones extranjeras. Aparece en formas tanto singulares indefinidas como plurales. Jeremias 10:11 declara que ''los dioses que no hicieron los cielos y la tierra pereceran'', y Daniel 3:12-18 narra la negativa a adorar la imagen de oro de Nabucodonosor. El uso plural e indefinido confirma la distincion entre el Dios verdadero y la divinidad generica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82391, 'spa', 'estos, estas (demostrativo)', 'Pronombre demostrativo plural de proximidad, usado para indicar un conjunto de referentes ya introducidos o que se especificaran a continuacion en el discurso. Encabeza con frecuencia listas formulaicas (Gen 10:20 ''estos son los hijos de Cam'') y enumeraciones legales (Dt 18:12 ''estas cosas''). Las 746 apariciones, incluidos los compuestos preposicionales, expresan una unica funcion deictica sin variacion semantica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82415, 'spa', 'Dios (de Israel, dominante)', 'El Dios de Israel en su sentido dominante con 2.502 apariciones, abarcando a Dios como creador, pactante, legislador, juez y redentor. Usado con articulo, en cadenas constructas, con sufijos pronominales y tras preposiciones. Concuerda con verbos en singular pese a su morfologia plural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82429, 'spa', 'dioses (colectivo pagano)', 'Dioses paganos en conjunto: 81 apariciones donde אֱלֹהִים funciona como plural genuino refiriendose a las deidades de las naciones circundantes. ''Quitad los dioses ajenos'' (Gn 35:2), ''contra todos los dioses de Egipto ejecutare juicios'' (Ex 12:12), ''no tendras dioses ajenos delante de mi'' (Ex 20:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82443, 'spa', 'dios o diosa (extranjero)', 'Un solo dios o diosa extranjera: 14 apariciones donde אֱלֹהִים designa a una deidad pagana individual por nombre o en cadena constructa. ''Dagon, su dios'' (Jue 16:23-24), ''Astoret, diosa de los sidonios'' (1 Re 11:5, 33), ''el dios de Ecron'' (2 Re 1:2-3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82475, 'spa', 'uso ambiguo o comparativo', 'Usos contextualmente ambiguos o comparativos: 2 apariciones (Ex 29:45, Jue 8:33) donde אֱלֹהִים aparece en una construccion que podria analizarse como ''Dios'' o ''un dios'' segun el marco interpretativo. Las glosas multilingues se dividen, reflejando una genuina incertidumbre hermeneutica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82495, 'spa', 'Interjección exclamativa', 'Interjección exclamativa que significa ''¡he aquí!'', usada para captar la atención dentro de relatos visionarios. Aparece siempre en Daniel como וַאֲלוּ (''y he aquí'') para introducir elementos dramáticos: la gran estatua del sueño de Nabucodonosor (Dn 2:31), el árbol cósmico (Dn 4:10), el vigilante celestial (Dn 4:13) y el cuerno pequeño (Dn 7:8, con doble énfasis).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82497, 'spa', 'Dios, el Dios verdadero', 'Dios, el Dios verdadero. El unico Dios verdadero de Israel. Este es con mucho el uso dominante, portando todo el peso teologico del nombre divino en registro poetico. Solo Job concentra la mayoria de las ocurrencias, donde Eloah aparece en los discursos de Job, Elihu y los discursos divinos mismos (p. ej., Job 3:4, 3:23). El espanol traduce consistentemente ''Dios'' con mayuscula, el frances ''Dieu'' y el aleman ''Gott''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82498, 'spa', 'un dios, deidad', 'un dios, deidad. Un dios o deidad en general, aplicado a seres divinos distintos del Dios de Israel. Este sentido aparece en contextos tardios en prosa como Daniel 11:37-39, donde el rey ''no hara caso del dios de sus padres'', y 2 Cronicas 32:15, donde Ezequias advierte contra la capacidad de cualquier dios para librar. El ingles cambia a ''a god'', el espanol a ''dios'' en minuscula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82505, 'spa', 'dioses, falsas deidades', 'dioses, falsas deidades. Dioses o falsas deidades, apareciendo en variantes textuales donde el singular Eloah figura como lectura Ketiv frente al Qere plural Elohim. El caso mas claro es 2 Reyes 17:31, donde los paganos de Sefarvaim adoran a sus dioses. El ingles y el frances anotan parenteticamente ''(elohim de)'', senalando que la tradicion escribal resolvio este singular hacia el plural mas esperado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82513, 'spa', 'Encina, terebinto (árbol)', 'Árbol grande y sagrado —encina o terebinto— que sirve como punto de referencia en designaciones topográficas y cultuales. Aparece sistemáticamente en estado constructo con un nombre calificativo: «encina de Moré» (Gn 12:6; Dt 11:30), «encinas de Mamre» (Gn 13:18; 14:13; 18:1), la «encina de los adivinos» (Jue 9:37) y la «encina en Zaananim» (Jue 4:11). Estos árboles marcaban lugares de revelación, pacto y juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82516, 'spa', 'Encina (árbol)', 'Sustantivo masculino אַלּוֹן que designa la encina (Quercus), distinta del terebinto (אֵלָה) aunque a veces confundida en traducciones antiguas. Aparece en la narrativa como marcador conmemorativo: la encina de la sepultura de Débora en Betel (Gn 35:8, «encina del llanto»). Proféticamente simboliza fortaleza y orgullo imponente: las «encinas de Basán» representan lo que Dios abatirá (Is 2:13; Zac 11:2), y Amós las emplea como imagen de lo que será derribado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82526, 'spa', 'Amigo íntimo, compañero', 'Amigo cercano, compañero de confianza o confidente íntimo. El paralelo con מְיֻדָּע («conocido») en el Salmo 55:13 subraya la profundidad de este vínculo. Proverbios 16:28 y 17:9 advierten que el chisme separa incluso a amigos tan cercanos. En Proverbios 2:17 y Jeremías 3:4 el término se extiende al vínculo matrimonial —el esposo como compañero de vida—, llegando a llamar al propio YHWH «compañero» de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82528, 'spa', 'Manso, dócil', 'Manso, apacible, dócil: el sentido adjetival que conserva el significado raíz de estar domesticado o amaestrado. Jeremías 11:19 lo emplea en el conmovedor símil «como cordero manso llevado al matadero», donde la inocencia confiada del cordero es el punto central. Este sentido ilumina cómo la intimidad (sentido 1) deriva metafóricamente de la mansedumbre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82531, 'spa', 'Ganado, bueyes', 'Ganado o bueyes, probablemente una variante de אֶלֶף. En el Salmo 144:14, «nuestros bueyes están bien cargados» (אַלּוּפֵינוּ מְסֻבָּלִים) describe la prosperidad agrícola. La evidencia multilingüe confirma esta lectura: español «nuestros bueyes», francés «nos boeufs» y alemán «unser Vieh» traducen como ganado, distinguiéndolo claramente de los sentidos de «amigo» o «jefe» que se hallan en otros pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82534, 'spa', 'Jefe o cabecilla tribal, usado casi exclusivamente para los líderes de los subcl', 'Jefe o cabecilla tribal, usado casi exclusivamente para los líderes de los subclanes edomitas en el registro genealógico de Génesis 36 (vv. 15-43) y su paralelo en 1 Crónicas 1:51-54. El término también aparece en el Cántico del Mar (Éx 15:15) donde los jefes de Edom tiemblan, y en Zacarías 12:5-6 para los clanes de Judá. Las traducciones interlingüísticas — español jefe, francés chef, alemán Häuptling — confirman el sentido central de liderazgo tribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82542, 'spa', 'Corrupción moral', 'Los Salmos 14:3 y 53:3 declaran con lenguaje idéntico que «todos se corrompieron», un veredicto radical sobre la condición moral de la humanidad. Job 15:16 intensifica la imagen: «¡cuánto más el hombre abominable y corrupto, que bebe la injusticia como agua!» La forma verbal enfatiza el proceso de corromperse, no un estado estático. Las traducciones multilingües confirman este matiz de transformación degenerativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82543, 'spa', 'Nombre propio Eljanán', 'El nombre personal Eljanán, que significa ''Dios ha sido misericordioso''. Designa a dos guerreros de élite de David: Eljanán hijo de Jaaré-Oregim, quien abatió a un gigante filisteo (2 S 21:19 // 1 Cr 20:5), y Eljanán hijo de Dodó de Belén, incluido entre los Treinta (2 S 23:24 // 1 Cr 11:26). Las traducciones al español lo transliteran habitualmente como ''Eljanán''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82544, 'spa', 'Nombre propio teofórico que significa ''mi Dios es padre,'' llevado por múltiples ', 'Nombre propio teofórico que significa ''mi Dios es padre,'' llevado por múltiples figuras del AT. Los más prominentes son el hermano mayor de David, rechazado para el reinado a pesar de su imponente estatura (1 S 16:6), y el rubenita padre de los rebeldes Datán y Abiram (Nm 16:1). También designa a un príncipe de Zabulón (Nm 1:9), un guerrero gadita y músicos levitas.');